let num = 0, den = 1; 
let fractions = expression.match(/[+-]?[0-9]+/g); 
for(let i = 0; i < fractions.length; i += 2) { 
  let n = parseInt(fractions[i]), d = parseInt(fractions[i+1]); 
  num = num * d + n * den; 
  den = den * d; 
  let common = gcd(Math.abs(num), den); 
  num /= common; den /= common; 
}
